#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(max(N,2), true);
        sieve[0]=false; sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    auto getmult = [&](int step, int src) -> double {
        return (step%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += ddist(t[s-1],t[s]) * getmult(s, t[s-1]);
        }
        return cost;
    };

    // Grid-based nearest neighbor
    double minx=1e18, maxx=-1e18, miny=1e18, maxy=-1e18;
    for(int i=0;i<N;i++){
        minx=min(minx,cx[i]); maxx=max(maxx,cx[i]);
        miny=min(miny,cy[i]); maxy=max(maxy,cy[i]);
    }

    int gridSize = max(1, (int)sqrt((double)N / 4.0));
    double cellW = (maxx-minx)/gridSize + 1e-9;
    double cellH = (maxy-miny)/gridSize + 1e-9;
    if(cellW < 1e-12) cellW = 1.0;
    if(cellH < 1e-12) cellH = 1.0;

    auto getCellXY = [&](double x, double y) -> pair<int,int> {
        int gx = min(gridSize-1, max(0,(int)((x-minx)/cellW)));
        int gy = min(gridSize-1, max(0,(int)((y-miny)/cellH)));
        return {gx, gy};
    };
    auto getCellIdx = [&](int gx, int gy) -> int {
        return gy*gridSize+gx;
    };

    vector<vector<int>> grid(gridSize*gridSize);
    for(int i=0;i<N;i++){
        auto [gx,gy] = getCellXY(cx[i],cy[i]);
        grid[getCellIdx(gx,gy)].push_back(i);
    }

    auto gridNN = [&](int startCity) -> vector<int> {
        // Make a copy of grid
        vector<vector<int>> lgrid = grid;
        vector<bool> visited(N, false);
        vector<int> t(N+1);
        t[0] = startCity;
        visited[startCity] = true;
        {
            auto [gx,gy] = getCellXY(cx[startCity],cy[startCity]);
            auto &v = lgrid[getCellIdx(gx,gy)];
            v.erase(find(v.begin(),v.end(),startCity));
        }

        for(int step=1;step<N;step++){
            int last = t[step-1];
            auto [gx0,gy0] = getCellXY(cx[last],cy[last]);

            int best=-1; double bestD=1e30;
            for(int rad=0;rad<=2*gridSize;rad++){
                if(best!=-1){
                    double minPossible = max(0.0, (double)(rad-1)) * min(cellW, cellH);
                    if(minPossible > bestD*1.5) break;
                }
                int found = 0;
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0+dx, gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        auto &v=lgrid[getCellIdx(gx,gy)];
                        for(int id : v){
                            if(!visited[id]){
                                double d=ddist(last,id);
                                if(d<bestD){bestD=d;best=id;}
                                found++;
                            }
                        }
                    }
                }
                if(best!=-1 && rad>0) break;
            }
            t[step]=best;
            visited[best]=true;
            auto [gxb,gyb] = getCellXY(cx[best],cy[best]);
            auto &v = lgrid[getCellIdx(gxb,gyb)];
            v.erase(find(v.begin(),v.end(),best));
        }
        t[N]=startCity;
        return t;
    };

    // Build initial tour using NN from city 0
    vector<int> tour = gridNN(0);

    // Ensure tour starts and ends at 0
    // It should since we started from 0
    // But if not, rotate
    if(tour[0]!=0){
        int zp=-1;
        for(int i=0;i<N;i++) if(tour[i]==0){zp=i;break;}
        vector<int> rt(N+1);
        for(int i=0;i<N;i++) rt[i]=tour[(zp+i)%N];
        rt[N]=0;
        tour=rt;
    }

    double curCost = tourCost(tour);

    // Also try the x-sorted baseline and keep better
    {
        vector<int> baseline(N+1);
        baseline[0]=0;
        for(int i=1;i<N;i++) baseline[i]=i;
        baseline[N]=0;
        double bc = tourCost(baseline);
        if(bc < curCost){
            tour = baseline;
            curCost = bc;
        }
    }

    // 2-opt local search with penalty awareness
    // For efficiency, use limited window 2-opt

    auto edgeCost = [&](int step, int from, int to) -> double {
        return ddist(from,to) * getmult(step, from);
    };

    bool improved = true;
    int passCount = 0;

    while(improved && elapsed() < 1.8){
        improved = false;
        passCount++;

        // 2-opt with window
        int window = min(N-1, max(50, N/10));
        if(N > 50000) window = 30;
        if(N > 100000) window = 20;

        for(int i=1; i<N-1 && elapsed()<1.75; i++){
            for(int j=i+1; j<min(i+window, N); j++){
                // Reverse tour[i..j]
                // Affected steps: i to j+1 (at most)
                int lo = i, hi = min(j+1, N);

                // Compute old cost for steps lo..hi
                double oldC = 0;
                for(int s=lo; s<=hi; s++)
                    oldC += edgeCost(s, tour[s-1], tour[s]);

                // Reverse
                reverse(tour.begin()+i, tour.begin()+j+1);

                double newC = 0;
                for(int s=lo; s<=hi; s++)
                    newC += edgeCost(s, tour[s-1], tour[s]);

                if(newC < oldC - 1e-10){
                    curCost += newC - oldC;
                    improved = true;
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }

        // Or-opt: relocate single cities
        for(int i=1; i<N && elapsed()<1.75; i++){
            int city = tour[i];
            // Try moving city to nearby positions
            int bestJ = -1;
            double bestDelta = -1e-10;

            int range = min(60, N-2);
            for(int j=max(1,i-range); j<=min(N-1,i+range); j++){
                if(j==i) continue;

                int lo = min(i,j), hi = max(i,j);
                double oldC=0;
                for(int s=lo;s<=min(hi+1,N);s++) oldC+=edgeCost(s,tour[s-1],tour[s]);

                // Simulate move
                int c = tour[i];
                vector<int> seg;
                for(int k=lo-1;k<=min(hi+1,N);k++){
                    if(k==i) continue;
                    if(j>i && k==j) { seg.push_back(tour[k]); seg.push_back(c); }
                    else if(j<i && k==j) { seg.push_back(c); seg.push_back(tour[k]); }
                    else seg.push_back(tour[k]);
                }

                double newC=0;
                for(int k=1;k<(int)seg.size();k++){
                    int step=lo+k-1;
                    if(step>=1&&step<=N) newC+=edgeCost(step,seg[k-1],seg[k]);
                }

                double delta=newC-oldC;
                if(delta<bestDelta){bestDelta=delta;bestJ=j;}
            }

            if(bestJ>=0){
                int city2=tour[i];
                if(bestJ>i){
                    for(int k=i;k<bestJ;k++) tour[k]=tour[k+1];
                    tour[bestJ]=city2;
                } else {
                    for(int k=i;k>bestJ;k--) tour[k]=tour[k-1];
                    tour[bestJ]=city2;
                }
                curCost+=bestDelta;
                improved=true;
            }
        }
    }

    // Prime swap optimization: try to place primes at penalty positions
    // Penalty positions are steps 10,20,30,... i.e. tour indices 9,19,29,...
    // The source city at step t is tour[t-1], so for step 10, source is tour[9]
    while(elapsed() < 1.9){
        bool imp2 = false;
        for(int t=10; t<=N; t+=10){
            int pos = t-1; // tour[pos] is source of step t
            if(is_prime[tour[pos]]) continue; // already prime
            // Find nearest prime to swap with
            double bestDelta = -1e-10;
            int bestK = -1;
            for(int k=max(1,pos-200); k<min(N,pos+200); k++){
                if(k==pos) continue;
                if(!is_prime[tour[k]]) continue;
                // Try swapping tour[pos] and tour[k]
                // Affected steps: pos, pos+1, k, k+1
                set<int> affected = {pos, pos+1, k, k+1};
                double oldC=0, newC=0;
                for(int s : affected){
                    if(s>=1&&s<=N) oldC+=edgeCost(s,tour[s-1],tour[s]);
                }
                swap(tour[pos],tour[k]);
                for(int s : affected){
                    if(s>=1&&s<=N) newC+=edgeCost(s,tour[s-1],tour[s]);
                }
                double delta=newC-oldC;
                if(delta<bestDelta){bestDelta=delta;bestK=k;}
                swap(tour[pos],tour[k]);
            }
            if(bestK>=0){
                swap(tour[pos],tour[bestK]);
                curCost+=bestDelta;
                imp2=true;
            }
        }
        if(!imp2) break;
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
